import numpy as np
import json

arr = np.array(test_input)

# Try: neighbor-majority rule - each cell takes the majority value of its 8 neighbors
# If no majority, maybe stays same or takes some default

def neighbor_majority(arr, force_flip=False):
    """Cell takes value of most common neighbor (8-connectivity)"""
    h, w = arr.shape
    output = np.zeros_like(arr)
    for r in range(h):
        for c in range(w):
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        neighbors.append(arr[nr, nc])
            if neighbors:
                majority = max(set(neighbors), key=neighbors.count)
                output[r, c] = majority
            else:
                output[r, c] = arr[r, c]
    return output

output_neighbor = neighbor_majority(arr)
action_json = json.dumps({"action": "submit", "grid": output_neighbor.tolist()})
print("Submitting neighbor-majority hypothesis...")

# Also try: inverse neighbor majority (each cell takes minority)
def neighbor_minority(arr):
    """Cell takes minority value of its 8 neighbors"""
    h, w = arr.shape
    output = np.zeros_like(arr)
    for r in range(h):
        for c in range(w):
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        neighbors.append(arr[nr, nc])
            if len(neighbors) > 0:
                # Find minority - less frequent value
                from collections import Counter
                counts = Counter(neighbors)
                minority = [v for v, c in counts.items() if c == min(counts.values())][0]
                output[r, c] = minority
            else:
                output[r, c] = arr[r, c]
    return output

output_minority = neighbor_minority(arr)
action_json = json.dumps({"action": "submit", "grid": output_minority.tolist()})
print("Submitting neighbor-minority hypothesis...")

